package com.assetsphere.modules.asset; import java.time.Instant; import java.util.UUID; import jakarta.persistence.*; import lombok.Getter; import com.assetsphere.modules.common.BaseEntity;
@Getter @Entity @Table(name="idempotency_records") public class IdempotencyRecord extends BaseEntity { @Column(name="idempotency_key",nullable=false,length=128) private String idempotencyKey; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="workspace_id",nullable=false) private UUID workspaceId; @Column(name="operation_type",nullable=false,length=64) private String operationType; @Column(name="request_fingerprint",nullable=false,length=64) private String requestFingerprint; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private IdempotencyStatus status; @Column(name="resource_id") private UUID resourceId; @Column(name="response_status") private Integer responseStatus; @Column(name="response_body") private String responseBody; @Column(name="expires_at",nullable=false) private Instant expiresAt; protected IdempotencyRecord(){} public static IdempotencyRecord reserve(String key,UUID userId,UUID workspaceId,String fingerprint,Instant expiresAt){IdempotencyRecord record=new IdempotencyRecord();record.idempotencyKey=key;record.userId=userId;record.workspaceId=workspaceId;record.operationType="ASSET_UPLOAD";record.requestFingerprint=fingerprint;record.status=IdempotencyStatus.IN_PROGRESS;record.expiresAt=expiresAt;return record;} public void complete(UUID resourceId,int responseStatus,String responseBody){this.resourceId=resourceId;this.responseStatus=responseStatus;this.responseBody=responseBody;this.status=IdempotencyStatus.COMPLETED;} }
